/* Round 2 content (22 Nov): AI module, company deep dives, MarkSoc gaps, casebook bank.
   Casebook entries are summarised in our own words from the IIM Ahmedabad Consult Club Case Book 2025-26 (IIMA)
   and the IIM Calcutta Consult Club Case Book 2024-25 (IIMC); open the original book for the full transcript. */
const B = (id, kind, cat, ind, co, src, q, how) => ({ id, kind, cat, ind, co, src, q, how });

export const BANK2 = [
  // ---------- Profitability ----------
  B('x1', 'case', 'Profitability', 'Consumer services platform', ['clevertap'], 'IIMA #4', 'Urban Company is close to break-even and wants to improve its bottom line within a year.', `<p><b>Map the two-sided model first:</b> customers pay for services; partners pay platform fees and buy consumables. Split revenue by category (beauty is the biggest) and by side.</p><p><b>Customer side:</b> raise frequency with prepaid packs and subscriptions (which also lift retention), surge pricing at peak demand (festive cleaning), cross-sell categories.</p><p><b>Partner side:</b> don't raise platform fees: it pushes partners to deal with customers directly (disintermediation) and weakens network effects. Earn instead on tools and consumables sold below market price with delivery.</p><p><b>Cost side:</b> marketing efficiency, partner training cost per job, utilisation of partners' time.</p>`),
  B('x2', 'case', 'Profitability', 'Consumer durables', ['versuni'], 'IIMA #7', 'A water-purifier maker with 28% share earns lower EBITDA margins than its competitors, mainly in the residential segment.', `<p>Confirm the metric (EBITDA margin) and timeline. Place the client in the value chain: suppliers → manufacturer → distributor → retailer.</p><p>Compare revenue (price, volume, mix of RO vs UV) and costs (materials, manufacturing, distribution, marketing, after-sales service) against competitors, line by line. Look for where the gap sits: a single plant far from parts of the market raises logistics cost; service and AMC economics differ by player.</p><p><b>Close with</b> 2–3 fixes ranked by impact, e.g. regional assembly or warehousing, renegotiated distributor margins, a more profitable service/AMC model.</p>`),
  B('x3', 'case', 'Profitability', 'Consumer durables', ['versuni', 'titan'], 'IIMA #10', 'A battery maker\'s profits fell for six months; only its D-cell (torch) batteries are declining and its main rival is gaining.', `<p>Narrow down: D-cells, sold mostly in tier-2/rural markets, client-specific (rival up). So customers are switching.</p><p>Walk the customer journey and the channel: availability at rural retailers, distributor margins and schemes versus the rival, price, product life, and substitutes (rechargeable LED torches).</p><p>The lesson: when a rival grows while you shrink in the same market, check <b>distribution and trade incentives</b> before blaming demand.</p>`),
  B('x4', 'case', 'Growth diagnosis', 'Quick-service restaurants', ['titan'], 'IIMA #12', 'A US fast-food chain in India (market leader, mass-premium) sees revenue growth slow, most sharply in tier-1 cities.', `<p>Revenue = price × volume. Prices tracked inflation, so it's volume. Supply isn't the constraint (still expanding), so it's demand.</p><p>Split demand into market-level (slower eating out, health trends, delivery apps changing habits) and firm-level (new competitors in tier-1, menu fatigue, store experience, value perception versus local QSRs).</p><p>Recommend by cause: menu localisation and value meals, delivery partnerships, refreshing flagship tier-1 stores, loyalty app.</p>`),
  B('x5', 'case', 'Profitability (ROCE)', 'Fashion retail', ['titan'], 'IIMA #20', 'A leading textile retailer\'s return on capital fell 4% in a year while peers held steady.', `<p>ROCE = operating profit ÷ capital employed. Profit is flat; capital went up. Split capital into fixed (stores, fit-outs) and working capital (inventory, receivables, payables).</p><p>The likely culprit in retail: <b>inventory build-up</b> (slow-moving stock, poor sell-through, longer supplier lead times) or new stores not yet productive.</p><p>Fixes: assortment planning and demand forecasting, end-of-season clearance, better supplier terms, store productivity reviews.</p>`),
  B('x6', 'case', 'Profitability', 'Grocery retail', ['titan', 'versuni'], 'IIMA #23', 'A single grocery store next to a metro station has seen profits fall 5–10% in a year; nearby stores are fine.', `<p>Revenue = people in the catchment × % who enter × % who buy × ticket size. Footfall into the store fell.</p><p>Check awareness, accessibility (construction, parking, entrance), price, and range; then walk the in-store journey (layout, queues, stock-outs).</p><p>A store-specific drop with a healthy market points to something local and physical. Fix the access or experience issue first, then win back with offers.</p>`),
  // ---------- Market entry / GTM ----------
  B('x7', 'case', 'Market entry', 'Consumer internet', ['clevertap', 'google'], 'IIMA #29', 'A UK market-leading dating app (freemium) wants to enter India, where two players hold ~80%.', `<p>Three tests: market attractiveness (size the paying base: urban → age 18–35 → smartphone → single → willing to pay for premium), economic viability (achievable share × ARPU), and operational viability (safety, local features, regulation, marketing cost).</p><p>Differentiation is essential against two incumbents: a niche (professionals, regional languages, safety-first), not "Tinder again".</p><p>Recommend with conditions: go, if a clear niche and a CAC that pays back within a year.</p>`),
  B('x8', 'case', 'Market entry / GTM', 'Personal care FMCG', ['titan', 'versuni'], 'IIMA #30', 'A US natural skin-care brand wants to enter India with face creams and break even in year one. Build the GTM.', `<p>Financial feasibility: market size × share × (price − variable cost) − fixed cost. With 5% share, ₹1,500 price and ₹800 variable cost, check break-even against fixed costs.</p><p>Barriers: two incumbents with 50% each, distribution reach, trust.</p><p><b>GTM:</b> premium women 18+, metros first; D2C site + marketplaces + beauty retail (Nykaa-type) rather than general trade; influencer and dermatologist-led content; sampling. Entry mode: imports first, local manufacturing later.</p>`),
  B('x9', 'case', 'Location choice', 'Electronics manufacturing', ['atci'], 'IIMA #31', 'A leading phone maker wants a new Asian plant (15 mn units/yr, $2 bn, 24 months). India, Vietnam or Indonesia?', `<p>Score each country on three dimensions: political and regulatory (stability, incentives like PLI, IP protection), ecosystem readiness (skilled labour, component suppliers, ports and power), financial and operational (land, labour, tax, logistics cost, time to build).</p><p>Weight by the objective (serve Asia-Pacific demand, diversify supply). India scores on market size, incentives and talent pool; Vietnam on export ecosystem; Indonesia lags on talent. Recommend with risks and a phased ramp-up.</p>`),
  B('x10', 'case', 'Market entry', 'Payments / fintech', ['pinelabs'], 'IIMA #33', 'A Dubai e-commerce leader (50%+ share) wants to enter fintech: a wallet, micro-loans, a stock broker or an insurance/credit-card marketplace?', `<p>Score the four options on market size, competition and <b>synergy with the existing business</b>. In a cash-heavy market with no fintech players, a wallet fits best: it reduces cash-on-delivery, uses the existing customer base, and becomes the base for lending and insurance later.</p><p>Then GTM: wallet at checkout with cashback, merchant acceptance outside the platform, regulatory licences, and a sequenced roadmap (pay → credit → insurance).</p>`),
  B('x11', 'case', 'Market entry', 'Online gaming', ['clevertap', 'google'], 'IIMA #34', 'A casino-games app with stagnant users wants to enter fantasy football (real money, KYC, 10% cut per game) using ₹200 coupons.', `<p>Evaluate: addressable users (18+ only), conversion from casino users to fantasy, coupon cost vs lifetime value, KYC drop-off, and competition (rivals focus on cricket, so football is a niche).</p><p>Compute break-even: coupon spend per acquired user vs. 10% rake × games per month × months retained.</p><p>Recommend tighter coupon conditions (minimum games), onboarding that eases KYC, and retention journeys (a CleverTap-style problem).</p>`),
  B('x12', 'case', 'GTM', 'Food retail', ['titan'], 'IIMC #29', 'An ice-cream franchise wants to open an outlet inside a Chennai cricket stadium. Build the GTM.', `<p>Demand: match days × attendance × % who buy × items × price, plus non-match events. Costs: rent/revenue share with the stadium, staff, cold chain.</p><p>Operations: quick-service format, limited menu, multiple counters or vendors in the stands, digital ordering to seats.</p><p>Brand value matters too: visibility to a mass audience. Recommend a pilot season with clear break-even per match.</p>`),
  B('x13', 'case', 'Online entry', 'Apparel & fabric retail', ['titan'], 'IIMC #32', 'Raymond (offline in 60 cities, stagnating) wants to go online. Devise the end-to-end strategy.', `<p>Pick markets: cities where Raymond has no stores but strong brand awareness; target professionals buying suits and occasion wear.</p><p>Proposition: fabric + stitching with home measurement or a size-recommendation tool, easy alterations.</p><p>Channel: own D2C site plus marketplaces; stores as fulfilment and alteration hubs (omnichannel). Marketing: search and social around weddings and festive seasons. KPIs: online share of sales, return rate, CAC.</p>`),
  // ---------- Pricing ----------
  B('x14', 'case', 'Pricing', 'Telecom', ['google'], 'IIMA #40', 'A large Indian telecom operator wants to price its first dedicated 5G plan.', `<p>Start from the 4G anchor (e.g. ~₹400/month for unlimited calls + 1.5 GB/day). Add premiums for speed, stability and value-added services (devices, OTT bundles), adjust for what customers will actually pay and for the competitor's move.</p><p>Consider tiers (good/better/best), introductory pricing to drive upgrades, and handset availability. Check that the price recovers spectrum and network investment over time.</p>`),
  B('x15', 'case', 'Pricing', 'Quick commerce', ['versuni', 'clevertap'], 'IIMA #41', 'A quick-commerce leader wants the monthly price for a membership: free standard and express delivery plus member discounts.', `<p>Value to the customer: delivery fees saved + discounts, by segment (heavy, medium, light users). Cost to the company: fees forgone + discounts funded.</p><p>Pick a price that heavy and medium users find worth it while staying profitable after the extra orders it drives (frequency uplift). Check competitor memberships. Consider a trial month and an annual plan.</p>`),
  B('x16', 'case', 'Pricing', 'Consumer goods', ['versuni', 'titan'], 'IIMC #35', 'A maker has a toothbrush that lasts a lifetime. What should it cost?', `<p>Three anchors: cost (R&D recovery + unit cost), competition (regular brushes × replacements over a lifetime), and value (convenience, sustainability).</p><p>Customers rarely pay for 60 years of value upfront: discount heavily for time and doubt, and consider replacement heads or a subscription. Think about cannibalising the client's own regular brushes.</p>`),
  // ---------- Growth ----------
  B('x17', 'case', 'Growth', 'Media', ['google'], 'IIMA #46', 'An English national newspaper recovered after covid but grows slowly. Grow revenue.', `<p>Revenue = circulation + advertising (+ add-ons). Levers: digital subscriptions and paywall, e-paper, regional editions, events and supplements, targeted print and digital ad packages, data-driven ad sales to local businesses.</p><p>Prioritise digital: subscriptions plus programmatic and direct digital ads, measured by ARPU and ad yield.</p>`),
  B('x18', 'case', 'Growth', 'Apparel', ['titan'], 'IIMA #47', 'A mid-priced US jeans maker wants 25% revenue growth.', `<p>Ansoff: existing products in new segments or regions, new products (jackets, women's, kids'), new channels (D2C, marketplaces, international).</p><p>Quantify each lever's share of the 25% and its risk. Usually: D2C and online + adjacent categories under the same brand give most of it.</p>`),
  B('x19', 'case', 'Growth (B2B SaaS)', 'B2B SaaS', ['clevertap', 'ibm'], 'IIMA #48', 'A B2B logistics SaaS ($20 mn ARR, +15%/yr) wants to grow 40% a year for two years. Market expansion is the suggested lever.', `<p>Size the gap first: organic growth gives ~$23 mn; 40% needs ~$28 mn, so ~$5 mn of new ARR.</p><p>Levers: new geographies (pick by logistics spend, digital readiness, competition, ease of selling), new segments (mid-market), upsell and cross-sell to existing clients (raise NRR), pricing and packaging, partnerships with system integrators.</p><p>Expansion alone rarely gets there quickly. Combine one new region with an NRR push.</p>`),
  B('x20', 'case', 'Growth diagnosis', 'E-grocery / quick commerce', ['versuni', 'clevertap'], 'IIMA #50', 'An e-grocery player with quick and slotted delivery sees muted growth: its share is flat but the market shrank.', `<p>Customers = market size × share. The market shrank, so ask why: customers moving to quick-commerce specialists, lower frequency, or measurement issues (which services count).</p><p>Shift investment toward the faster-growing format (quick delivery), deepen assortment, and use retention journeys to raise frequency.</p>`),
  B('x21', 'case', 'Growth', 'Apparel retail', ['titan'], 'IIMA #51', 'FashionX, saturated on the US West Coast, grows only at market rate (offline 1%, online 11%).', `<p>Saturation explains the slowdown. Options: expand to the rest of the US (similar competition, known market), push online, new segments or products (brand extensions), international later.</p><p>Recommend online-led expansion into new US regions first, with stores in high-potential cities.</p>`),
  B('x22', 'case', 'Growth', 'OTT streaming', ['google', 'clevertap'], 'IIMA #54', 'OTTCo India (subscription-only, global parent) wants to double revenue in 5–6 years (~15% CAGR).', `<p>Revenue = subscribers × ARPU. Subscribers: regional and sports content, mobile-only cheaper plans, telecom bundles, tier-2 reach. ARPU: tiered plans, an ad-supported tier (new revenue stream), password-sharing rules.</p><p>Add advertising as a second revenue line. Check content cost per subscriber.</p>`),
  B('x23', 'case', 'Corporate strategy', 'E-commerce', ['google'], 'IIMA #55', 'Flipkart (55% GMV share vs one rival) wants a 3–5 year strategy for growth and profitability.', `<p>Growth: tier-2/3 users (vernacular, value), new categories (grocery, quick commerce), financial services (credit, BNPL), advertising (retail media), B2B.</p><p>Profitability: take-rate, ads revenue, logistics efficiency, returns reduction.</p><p>Retention: loyalty programme, selection and delivery parity with the rival.</p>`),
  B('x24', 'case', 'Growth', 'OTT streaming', ['google'], 'IIMA #59', 'A pan-India OTT has stagnated. Short-term (1 year) and long-term growth plan; top line only.', `<p>Short term: pricing tiers, bundles with telcos and devices, marketing around big releases, reduce churn with personalisation.</p><p>Long term: original regional content, live sports rights, ad tier, international diaspora, adjacent businesses (gaming, commerce) or acquisitions.</p>`),
  B('x25', 'case', 'Growth', 'E-commerce', ['google'], 'IIMC #43', 'Flipkart in 2017–18, in the top 4 cities only, growing 20%: strategy for 3–5 years.', `<p>Organic: new cities and vernacular, new categories, better app features. Inorganic: partnerships first (logistics, payments, brands), then acquisitions.</p><p>Tie each move to customer base and profitability goals, sequence them, and define KPIs.</p>`),
  B('x26', 'case', 'International expansion', 'B2B SaaS', ['clevertap', 'ibm'], 'IIMC #46', 'A US SaaS firm serving high-end Silicon Valley clients wants to expand overseas. What factors matter?', `<p>Market: demand from similar high-end clients, size, growth. Fit: product localisation, data-residency rules, language. Competition and pricing. Go-to-market: direct sales vs partners, time zones, support. Economics: CAC, payback, entry cost.</p><p>Pick 1–2 markets by score, pilot with anchor clients.</p>`),
  B('x27', 'case', 'Growth', 'Gaming', ['clevertap'], 'IIMC #51', 'A paid PC game with 5 mn loyal players, 90% in one country, has slowing growth. Grow it.', `<p>Levers: new markets (localisation), new platforms (console, mobile), new monetisation (in-game purchases, expansions, subscriptions), community and creator programmes, sequel or spin-offs.</p><p>Watch the risk of upsetting loyal players with aggressive monetisation.</p>`),
  // ---------- M&A / due diligence ----------
  B('x28', 'case', 'M&A', 'E-commerce + AI', ['ibm', 'atci'], 'IIMA #60', 'A ₹5,000 cr beauty e-commerce platform wants to buy a young AI startup for ₹250 cr. Should it?', `<p>Strategic fit: what the AI does (recommendations, virtual try-on, search), and how it lifts conversion, AOV or retention.</p><p>Value: incremental revenue (e.g. +x% conversion on ₹5,000 cr) and cost savings over 3–5 years vs ₹250 cr; compare with building in-house or licensing.</p><p>Risks: talent retention (acqui-hire), tech scalability, data privacy. Recommend with an earn-out tied to results.</p>`),
  B('x29', 'case', 'Due diligence', 'Quick commerce', ['versuni'], 'IIMA #66', 'A PE firm (first startup deal) wants commercial due diligence on an online grocery startup.', `<p>Market: addressable users by city, age, income, occupation; growth. Company: share, unit economics (AOV, take-rate, delivery cost, contribution margin), cohort retention, path to profit. Competition and moats. Management and execution.</p><p>Recommendation with valuation sensitivities.</p>`),
  B('x30', 'case', 'Due diligence', 'Quick commerce', ['versuni'], 'IIMA #69', 'An e-commerce leader wants to buy a fulfilment partner with 45 micro-warehouses in 30 tier-2 cities to expand quick commerce.', `<p>Objective: speed to market vs build. Check the asset (locations, capacity, utilisation, tech), demand in those cities, unit economics per dark store, integration with the client's systems, people, and price vs the cost and time of building.</p>`),
  B('x31', 'case', 'M&A', 'AI', ['ibm', 'google', 'atci'], 'IIMA #70', 'A global electronics maker wants to buy a $500 mn AI company to fix its underperforming AI assistant.', `<p>Why buy: capability gap and speed. Assess the target's tech (model quality, benchmarks), talent, IP, integration across devices, data and privacy, and alternatives (partner with a model provider).</p><p>Value: devices sold × uplift in sales or retention from a better assistant + avoided R&D cost.</p>`),
  // ---------- Digital & tech transformation ----------
  B('x32', 'case', 'AI use cases', 'Banking', ['atci', 'ibm'], 'IIMA #75', 'A Hong Kong bank wants GenAI use cases to improve efficiency.', `<p>GenAI suits unstructured text (documents, emails, filings, chats); traditional ML suits numbers (credit scoring, fraud).</p><p>Walk the bank's value chain: customer service (assistants), operations (KYC documents, trade finance), risk and compliance (regulatory filings, monitoring news), relationship managers (meeting prep), IT (code). Prioritise by value × feasibility × risk, pilot with human review and governance.</p>`),
  B('x33', 'case', 'Digital transformation', 'Retail', ['atci', 'titan'], 'IIMA #81', 'A traditional big-box retailer with little technology wants a digital transformation plan.', `<p>Walk the value chain: sourcing and inventory (demand forecasting, automated replenishment), stores (self-checkout, digital payments, footfall analytics), customers (app, loyalty, personalisation, omnichannel), back office (ERP, analytics).</p><p>Prioritise quick wins with clear ROI, then platforms. Change management for store staff.</p>`),
  B('x34', 'case', 'Digital transformation', 'FMCG', ['atci', 'versuni'], 'IIMA #84', 'A salty-snacks market leader wants to transform digitally.', `<p>By value chain: procurement (price forecasting), manufacturing (IoT, predictive maintenance), distribution (retailer ordering apps, route optimisation, distributor management systems), marketing (digital campaigns, D2C/quick commerce), and data (single view of sales).</p><p>Start where money leaks most (distribution visibility, stock-outs), measure, scale.</p>`),
  B('x35', 'case', 'Process automation', 'E-commerce', ['atci', 'clevertap'], 'IIMA #99', 'A large e-commerce player wants to choose which customer-service processes to automate.', `<p>Objective: cost, satisfaction or both. List processes (order status, delivery rescheduling, returns and refunds, payments, complaints). Score each on volume, repetitiveness, complexity and customer risk.</p><p>Automate high-volume, rule-based ones first (order tracking, rescheduling via chatbot); keep humans for complex complaints; add escalation rules and measure resolution time and CSAT.</p>`),
  B('x36', 'case', 'Digital transformation', 'Banking / lending', ['pinelabs', 'atci'], 'IIMA #108', 'A private bank with a strong gold-loan book wants to digitise gold loans end to end.', `<p>Map the current journey (application, gold valuation, KYC, disbursal, storage, repayment, release) and its pain points. Options: doorstep or branch-light valuation, app-based applications and top-ups, instant disbursal to UPI, digital repayment.</p><p>Risks: valuation accuracy, security, regulation. Pilot in one city, track turnaround time and cost per loan.</p>`),
  B('x37', 'case', 'Talent', 'IT services', ['atci'], 'IIMC #52', 'A top IT services firm sees fewer applications for its entry-level training programme.', `<p>Funnel: awareness → interest → application. Check pay versus rivals and startups, brand perception, role clarity (ERP support seen as unexciting), location, bond terms, and campus reach. Fix with a sharper employee value proposition, better roles and pay, and campus engagement.</p>`),
  // ---------- Digital engagement & online sales ----------
  B('x38', 'case', 'Digital engagement', 'Digital media', ['google'], 'IIMA #76', 'A news aggregator in the EU has lost traffic for 6–7 months after years of ~20% growth.', `<p>Define traffic, split new vs repeat users: new users still grow, repeat users fall. Check content quality, cost, and delivery. The cause was regulatory: a large cookie-consent banner on every visit (GDPR-style), hurting repeat visits.</p><p>Fix: remember consent, a lighter banner design, logged-in experiences, push and newsletter channels. Lesson: <b>segment the metric before guessing causes.</b></p>`),
  B('x39', 'case', 'Customer experience', 'Food delivery', ['clevertap', 'google'], 'IIMA #79', 'A food-delivery app\'s NPS in one city fell from 7.5 to 6.7.', `<p>Understand the survey (who, when, how). Walk the journey: discovery and app, restaurant choice, ordering and payment, delivery time and accuracy, food quality, support.</p><p>Find the step that worsened (often delivery delays or a fee change), fix it, and close the loop with detractors.</p>`),
  B('x40', 'case', 'Online sales', 'Fashion e-commerce', ['google', 'clevertap'], 'IIMA #93', 'An online fashion retailer has seen returns rise sharply.', `<p>Segment returns by reason (size, quality, mismatch with photos, late delivery, impulse buying), category, customer and seller.</p><p>Fixes: size guides and fit recommendations, better images and reviews, seller quality controls, return fees or restrictions for serial returners, try-and-buy where it pays.</p>`),
  B('x41', 'case', 'Loyalty & CRM', 'Fuel retail', ['clevertap', 'pinelabs'], 'IIMA #98', 'A petrol-pump chain\'s loyalty card is underperforming. Make it more attractive.', `<p>Walk the card's lifecycle: awareness, issuance (forms, days to issue, fees), earning (points rate vs rivals), redemption (ease, catalogue, partners), engagement (reminders).</p><p>Fixes: instant digital issuance on a mobile number, richer partner rewards, tiered benefits for fleets and frequent users, personalised offers. Measure repeat rate and share of wallet.</p>`),
  B('x42', 'case', 'Merchant acquisition', 'Payments', ['google', 'pinelabs'], 'IIMC #53', 'Google wants to onboard ~20 mn MSMEs (a third of the market) onto Google Pay for Business, quickly.', `<p>Hybrid approach: partnerships for a quick jump (choose partners by merchant count, growth, health, value both sides gain) plus organic growth through features and marketing.</p><p>Choose features by MSME category needs (e.g. inventory for small retail), scored on number of merchants, ease of building and impact. Use the same category lens to pick partners so both efforts reinforce each other.</p>`),
  // ---------- Operations ----------
  B('x43', 'case', 'Supply chain', 'FMCG', ['atci', 'versuni'], 'IIMA #103', 'A frozen-dough maker\'s spoilage is 7.5% after FIFO, versus a 2.5% industry average.', `<p>Walk the cold chain: production, storage at the plant, transport, distributor storage, retailer freezers. Look for temperature breaks, long dwell times, over-ordering by retailers, packaging.</p><p>Fix the weakest link (often last-mile and retailer freezers): better forecasting, smaller and more frequent deliveries, temperature monitoring.</p>`),
  B('x44', 'case', 'Salesforce effectiveness', 'FMCG staples', ['versuni', 'titan'], 'IIMA #105', 'A staples FMCG company (dal, rice, oil) has poor salesforce effectiveness.', `<p>Define effectiveness (sales per rep, strike rate, lines per call, coverage). Diagnose: beat design, outlet classification, targets and incentives, training, tools (sales apps), distributor support.</p><p>Fix: redesign beats by outlet potential, align incentives to secondary sales and distribution, give reps an order-taking app with suggested orders.</p>`),
  B('x45', 'case', 'Cost reduction', 'Mobility platform', ['atci'], 'IIMA #106', 'A Mumbai cab aggregator\'s costs have risen; improve operating efficiency.', `<p>Map costs: driver incentives, customer discounts, payment fees, tech, support, marketing. Main levers: incentive design (pay for utilisation, not just trips), dead-mileage reduction through better matching, pooling, surge management, support automation.</p>`),
  B('x46', 'case', 'Competitive response', 'Grocery retail', ['titan'], 'IIMA #101', 'The largest discount grocer in West India (300 stores) faces a North Indian rival that bought its competitor\'s 200 stores. Should the CEO worry?', `<p>Understand why the client wins (scale, pricing, locations, supply chain). Assess the entrant: buying power, format, how fast it can convert stores, price wars.</p><p>Responses: protect key catchments, loyalty, private labels, supplier terms, and selective price matching rather than a full price war.</p>`),
  // ---------- Digital cases built for Google gTech-style rounds ----------
  B('x47', 'case', 'Digital engagement', 'Digital advertising', ['google'], 'Built for you', 'A gaming app\'s cost per install has risen 40% in three months while installs are flat. What do you check and do?', `<p>Split cost per install = cost per click ÷ install rate. Check auction competition (season, new rivals), creative fatigue, targeting changes, tracking (SDK, attribution changes), app-store page conversion.</p><p>Fixes: fresh creative variants and video, optimise to in-app actions not just installs (value of a user), store-page tests, broaden audiences with Smart Bidding.</p>`),
  B('x48', 'case', 'Online-to-offline', 'Digital advertising', ['google', 'titan', 'versuni'], 'Built for you', 'A furniture retailer with 60 stores sells 90% offline. How should it use Google to grow store sales?', `<p>Local campaigns and Performance Max with store-visit goals, Google Business Profile for every store, local inventory ads, YouTube for consideration, and measurement of store visits and offline sales (upload offline conversions).</p><p>Show the full funnel: search intent → store visit → sale, with a test to prove incrementality.</p>`),
  B('x49', 'case', 'Measurement', 'Digital advertising', ['google'], 'Built for you', 'A brand\'s CMO says YouTube is just awareness and wants to cut it. How do you show its value?', `<p>Agree the business goal. Run a brand-lift study (ad recall, consideration), a geo split test (regions with and without YouTube) for sales, and look at search lift for the brand. Use data-driven attribution, not last click.</p><p>Propose a test budget and a decision rule before cutting.</p>`),
  B('x50', 'case', 'Client retention', 'Digital advertising', ['google', 'clevertap'], 'Built for you', '30% of first-time small advertisers stop using Google Ads within 90 days. Fix it.', `<p>Diagnose by stage: setup (tracking, goals), first results (time to first lead), understanding (reporting jargon), value (cost per lead vs their margin).</p><p>Fixes: guided setup with conversion tracking, realistic expectations, a 30-day check-in from a strategist, simple business-language reports, local campaigns tied to calls and store visits.</p>`),
  B('x51', 'case', 'AI in search', 'Digital advertising', ['google'], 'Built for you', 'An education advertiser says organic and paid traffic both fell after AI summaries appeared in search. What do you advise?', `<p>Diagnose which queries lost clicks (informational vs high intent). Shift spend to high-intent and brand queries, use AI-powered campaign types and broad match with good conversion data, improve content so it is cited in AI answers (your GEO work), and measure leads, not just clicks.</p>`),
  B('x52', 'case', 'Festive campaign', 'Digital advertising', ['google'], 'Built for you', 'A D2C electronics brand wants to win the festive sale season with a fixed budget. Plan it on Google.', `<p>Phase it: pre-sale awareness (YouTube, Demand Gen), build audiences and remarketing lists, sale-week harvesting (Search, Shopping, PMax with festive feed), post-sale retention. Raise budgets and targets for the peak days, prepare creative and stock, and set daily checks.</p>`),
  // ---------- Guesstimates from the IIMA book ----------
  B('y1', 'guess', 'Digital', 'Digital advertising', ['google'], 'IIMA G2', 'Estimate the total duration of ads streamed on YouTube in a day.', `<p>Monthly users → daily users → remove premium and ad-blocker users → videos per user per day → ads per video (short vs long videos) → ad type mix (non-skippable full length, skipped after 5 s, watched) × duration. Sum the seconds. State which assumption swings it most (videos per day).</p>`),
  B('y2', 'guess', 'Consumer', 'Footwear retail', ['titan'], 'IIMA G4', 'Estimate pairs of shoes (closed shoes only) sold in Mumbai daily.', `<p>Population by income class → pairs owned per person → replacement cycle (upper ~8 months, middle ~13, lower ~26) → yearly pairs ÷ 365. Exclude sandals and slippers, add school shoes.</p>`),
  B('y3', 'guess', 'Market size', 'Home services', ['versuni'], 'IIMA G5', 'Estimate the home renovation market in Hyderabad.', `<p>Households by income → home ownership → house value by class → renovation spend as % of value (8–12%) → renovation cycle (every ~10 years). Sum by class.</p>`),
  B('y4', 'guess', 'Market size', 'Apparel', ['titan'], 'IIMA G6', 'Estimate the maternity wear market in India.', `<p>Women of child-bearing age → births a year (~2 children over ~30 years) → urban, by income → penetration (high for upper, lower for middle) → garments per pregnancy × price.</p>`),
  B('y5', 'guess', 'Revenue', 'Media / DTH', ['google'], 'IIMA G8', 'Estimate the monthly revenue of Tata Play subscribers in Delhi.', `<p>Households by income → TV penetration → share using DTH and Tata Play's share by class → average monthly recharge (₹300–500). Multiply and sum.</p>`),
  B('y6', 'guess', 'Digital', 'Social media', ['google', 'clevertap'], 'IIMA G10', 'Estimate Snapchat streaks sent in India per day.', `<p>Urban population → ages 13–40 → smartphone and social-media users by class → share on Snapchat → share who keep streaks → streaks per user per day.</p>`),
  B('y7', 'guess', 'Revenue', 'Entertainment', ['titan'], 'IIMA G17', 'Estimate the annual revenue of a multiplex in Ahmedabad.', `<p>Screens × seats × shows × occupancy (weekday vs weekend) × (ticket + share buying F&B × order value + parking). Per day, then × 365. F&B often rivals tickets on margin.</p>`),
  B('y8', 'guess', 'Market size', 'Personal care FMCG', ['versuni'], 'IIMA G18', 'Estimate the market for sanitary pads in India (units).', `<p>Women aged ~13–50 → urban/rural split → income-based penetration → pads per cycle × cycles a year.</p>`),
  B('y9', 'guess', 'Revenue', 'Consumer services platform', ['clevertap'], 'IIMA G19', 'Estimate Urban Company\'s annual revenue in Ahmedabad.', `<p>Households by income → addressable share → category penetration (salon, cleaning, repair, electrician) × frequency × ticket → GMV × commission (~25%) + subscriptions.</p>`),
  B('y10', 'guess', 'AI', 'AI', ['google', 'ibm', 'atci'], 'IIMA G21', 'Estimate ChatGPT prompts sent per day in India.', `<p>Urban population by city tier → internet users → share using ChatGPT (students, professionals) → active days → prompts per session. Add a small share for rural and tier-3. Compare: students and office users dominate.</p>`),
  B('y11', 'guess', 'Market size', 'Education', [], 'IIMA G22', 'Estimate the undergraduate test-prep market in India.', `<p>17–18-year-olds → enrolled in class 11–12 → aiming for competitive UG exams → share who take paid coaching (offline vs online) × fees.</p>`)];

/* AI fundamentals: general AI knowledge every panel can probe */
export const AI = { id: 'ai', n: 'AI: how it works and where it is going', d: 'General AI knowledge for any panel: how models work, agents, the landscape, use in marketing and consulting, and the risks. Check the very latest launches before an interview.', tp: [
  { k: 'llm', pri: 1.2, t: 'How large language models work', h: `<p><b>In one line:</b> an LLM predicts the next piece of text (a token), trained on huge amounts of text, which makes it able to write, summarise, reason and code.</p><ul><li><b>Tokens</b> are word pieces; models read and write in tokens, and price and limits are in tokens.</li><li><b>Transformer</b>: the architecture behind modern models; "attention" lets the model weigh which earlier words matter for the next one.</li><li><b>Pre-training</b> on broad data gives general ability; <b>fine-tuning</b> and <b>reinforcement learning from human (or AI) feedback</b> make it helpful and safe.</li><li><b>Context window:</b> how much text it can consider at once.</li><li><b>Multimodal</b> models take and produce images, audio and video too.</li><li><b>Hallucination:</b> confident but wrong output, because the model predicts plausible text, not checked facts.</li></ul><p><b>Say it simply:</b> "It's a very good pattern-completer; to trust it at work you ground it in your own data and check the output."</p>`, q: 'Explain how ChatGPT works to someone who has never used it.' },
  { k: 'stack', t: 'Prompting, RAG, embeddings and fine-tuning', h: `<ul><li><b>Prompting:</b> clear instructions, context, examples and the format you want. Most quality gains start here.</li><li><b>RAG (retrieval-augmented generation):</b> the system searches your documents and gives the relevant passages to the model, so answers use your data and can cite sources. The standard enterprise pattern.</li><li><b>Embeddings:</b> numbers that represent meaning, used to find similar text (semantic search).</li><li><b>Fine-tuning:</b> extra training on your examples for a specific style or task; costlier and needed less often than people think.</li><li><b>Evaluation:</b> test sets with known answers (your ground-truth testing), human review, accuracy and cost tracking.</li></ul><p><b>When to use which:</b> prompting first; RAG when the answer is in your documents; fine-tuning for a narrow repeated task.</p>`, q: 'A company wants an AI assistant that answers from its policy documents. How would you build it?' },
  { k: 'agents', pri: 1.2, t: 'Agents and agentic AI', h: `<p><b>An agent</b> is an AI system that pursues a goal over several steps: it plans, uses tools (search, code, apps, databases), checks results and continues, with a human approving key actions.</p><ul><li><b>Tools and connectors:</b> standards such as the Model Context Protocol (MCP) let models plug into apps and data.</li><li><b>Computer and browser use:</b> agents that click and type in software like a person.</li><li><b>Multi-agent systems:</b> several specialised agents (researcher, writer, checker) handing work to each other.</li><li><b>Where it works today:</b> coding, research, customer service, back-office workflows (invoices, reconciliations), marketing operations.</li><li><b>What makes it safe:</b> clear permissions, human checkpoints for anything irreversible, logs and audit trails, testing on real tasks.</li></ul><p><b>Interview line:</b> "Chatbots answer; agents do. The value moves from content to completed work, so process design and controls matter as much as the model."</p>`, q: 'What is agentic AI, and where would you use it first in a large company?' },
  { k: 'landscape', t: 'The AI landscape: models, companies, open vs closed', h: `<ul><li><b>Frontier model makers:</b> OpenAI (GPT, ChatGPT), Google (Gemini), Anthropic (Claude), Meta (Llama, open weights), xAI, Mistral, and Chinese labs such as DeepSeek and Alibaba (Qwen).</li><li><b>Closed vs open-weight models:</b> closed models via API are usually strongest; open-weight models can run on your own servers (control, cost, data residency).</li><li><b>Big vs small models:</b> small, cheap models handle simple high-volume tasks; large ones for hard reasoning.</li><li><b>The stack:</b> chips (Nvidia GPUs, Google TPUs) → cloud (AWS, Azure, Google Cloud) → models → platforms (watsonx, Vertex AI, Bedrock) → applications.</li><li><b>Trends:</b> falling cost per task, reasoning models that "think" before answering, agents, AI built into everyday software, India's own AI push (IndiaAI Mission, Indian-language models).</li></ul><p><b>Before any interview:</b> check the latest model launches from the company's competitors and partners.</p>`, q: 'Open-source or closed AI models for a bank in India: which and why?' },
  { k: 'aimkt', pri: 1.2, t: 'AI in marketing, advertising and sales', h: `<ul><li><b>Ads:</b> automated bidding and campaign types (Performance Max, Advantage+), AI-generated creative and variations, predictive audiences.</li><li><b>Search:</b> AI answers and summaries change clicks; GEO (being cited by AI engines) joins SEO.</li><li><b>Content:</b> copy, images and video at scale; the bottleneck becomes strategy and brand consistency.</li><li><b>Personalisation:</b> next-best offer, send-time and channel optimisation (CleverTap-style platforms).</li><li><b>Insight:</b> faster research, social listening, synthetic personas (use with care).</li><li><b>Sales:</b> lead scoring, call summaries, AI sales assistants, pitch personalisation.</li><li><b>Measurement:</b> modelled conversions and MMM as tracking gets harder.</li></ul><p><b>Your angle:</b> your GEO audit and LLM benchmarking show you can test AI, not just talk about it.</p>`, q: 'Will AI make marketers less needed? Defend your view.' },
  { k: 'aient', t: 'AI in consulting and the enterprise', h: `<ul><li><b>Where value comes from:</b> customer service, software engineering, marketing and sales, document-heavy operations (finance, procurement, HR, legal).</li><li><b>Copilots vs agents:</b> copilots help people work faster; agents take over defined workflows.</li><li><b>From pilot to scale:</b> many companies run pilots that never scale. Scaling needs a business case, clean data, integration with ERP/CRM, governance and change management.</li><li><b>Consulting firms</b> sell AI strategy, data platforms, implementation and managed services, and use AI to deliver projects faster.</li><li><b>Measuring ROI:</b> time saved, cost per transaction, error rates, revenue uplift, adoption.</li></ul><p><b>Interview line:</b> "The model is the easy part; data, process redesign and adoption decide whether AI pays back."</p>`, q: 'Why do most AI pilots fail to scale, and how would you fix that for a client?' },
  { k: 'risk', t: 'AI risks, governance and regulation', h: `<ul><li><b>Risks:</b> hallucination, bias, privacy leaks, security (prompt injection), copyright, over-reliance, job impact.</li><li><b>Governance:</b> approved use cases, data rules (no client data in public tools), human review, audit trails, model evaluation, an AI policy and owner.</li><li><b>Regulation:</b> the EU AI Act (risk-based rules); India's Digital Personal Data Protection Act; sector rules (RBI, SEBI); advertising and deepfake rules.</li><li><b>Responsible AI</b> is now a selling point for enterprise vendors (IBM, Google, Accenture).</li></ul><p><b>Your angle:</b> the Escalent task force was exactly this: trust, data safety and verification.</p>`, q: 'What guardrails would you put in place before letting staff use GenAI with client data?' },
  { k: 'aiopinion', t: 'Your three AI opinions', h: `<p>Panels like a clear, reasoned view. Prepare three, each: <b>view → 2 reasons → what would change your mind</b>.</p><ol><li><b>AI in search and ads:</b> will AI answers shrink or grow search advertising?</li><li><b>AI and jobs in marketing/consulting:</b> which tasks go, which grow (judgement, client relationships, strategy)?</li><li><b>Agents in the enterprise:</b> how fast will companies let AI act, not just suggest?</li></ol><p>Write yours in the notes box and say them out loud once.</p>`, q: 'What is your view on how AI will change the job you are interviewing for?' }] };

/* Extra marketing-core topics (gaps found against the FMS MarkSoc compendium) */
export const MKT2 = [
  { k: 'cb', t: 'Consumer behaviour: how people decide', h: `<ul><li><b>Buyer decision process:</b> need recognition → information search → evaluation of alternatives → purchase → post-purchase behaviour.</li><li><b>Influences:</b> cultural, social (family, reference groups), personal (age, life stage, income), psychological (motivation, perception, beliefs).</li><li><b>Maslow:</b> physiological → safety → belonging → esteem → self-actualisation; brands position at a level (Titan watches as esteem, insurance as safety).</li><li><b>AIDA:</b> attention → interest → desire → action; a lens for ads and landing pages.</li><li><b>Buying behaviour types:</b> complex (high involvement, big differences: cars), dissonance-reducing (high involvement, few differences), habitual (low involvement: salt), variety-seeking (snacks).</li><li><b>Roles in a purchase:</b> initiator, influencer, decider, buyer, user (key for families and B2B).</li><li><b>Customer lifecycle:</b> acquire → onboard → engage → retain → win back.</li></ul>`, q: 'Map the decision process for a family buying a mixer-grinder. Who plays which role?' },
  { k: 'product', t: 'Product: levels, mix, extensions and packaging', h: `<ul><li><b>Three levels:</b> core benefit (clean water), actual product (the purifier, brand, design), augmented product (installation, warranty, service).</li><li><b>Classification:</b> convenience, shopping, specialty, unsought (consumer); materials, capital items, supplies (industrial).</li><li><b>Product mix:</b> width (number of lines), length (items in total), depth (variants per item), consistency.</li><li><b>Line extension</b> (new flavour or size under the same brand) vs <b>brand extension</b> (brand into a new category) vs <b>line filling</b> (closing gaps in price points) vs line stretching (up or down market).</li><li><b>SKUs and packaging:</b> pack sizes for price points (sachets), shelf impact, protection, sustainability, information.</li></ul>`, q: 'Should Titan extend the Fastrack brand into a new category? Which one and why?' },
  { k: 'channel', t: 'Distribution design and the FMCG network', h: `<ul><li><b>What channels add:</b> time, place, possession and form utility; breaking bulk; credit; information.</li><li><b>Design decisions:</b> channel length (direct vs multi-level), intensity (intensive, selective, exclusive), number of intermediaries, conflict management.</li><li><b>Typical FMCG network:</b> factory → C&F agent → distributor/super-stockist → wholesaler → retailer → consumer; modern trade and e-commerce often direct from company or distributor.</li><li><b>Margin structure:</b> each layer earns a margin on its buying price; work out MRP-to-factory price backwards.</li><li><b>Distributor ROI</b> = distributor's profit ÷ investment (stock, credit, vehicles, people); a distributor stays only if ROI beats alternatives.</li></ul>`, q: 'Work out the margin chain from factory price to MRP for a ₹100 MRP product.' },
  { k: 'promo', t: 'Promotion mix: ATL, BTL, TTL, push and pull', h: `<ul><li><b>Promotion mix:</b> advertising, sales promotion, PR, personal selling, direct and digital marketing, events.</li><li><b>ATL</b> (mass media: TV, print, radio, outdoor) for reach; <b>BTL</b> (activations, sampling, in-store, direct) for targeted action; <b>TTL</b> (integrated, often digital) for both.</li><li><b>Push strategy:</b> incentives to trade so they push the product (schemes, margins, POSM). <b>Pull strategy:</b> consumer demand so shoppers ask for it (advertising, sampling).</li><li><b>Point-of-sale material (POSM):</b> danglers, standees, shelf strips, branded counters.</li><li><b>Sales promotions:</b> consumer (discounts, bundles, freebies, contests) vs trade (schemes, display incentives).</li></ul>`, q: 'Push or pull for a new kitchen appliance brand in tier-2 India? Justify.' },
  { k: 'types', t: 'Types of marketing and famous examples', h: `<ul><li><b>Experiential:</b> letting people live the brand (brand stores, pop-ups, events).</li><li><b>Ambush:</b> riding an event you don't sponsor (often sport) through clever association.</li><li><b>Cause marketing:</b> tying the brand to a social cause (needs authenticity).</li><li><b>Guerrilla:</b> low-cost, surprising, public stunts.</li><li><b>Surrogate:</b> advertising a restricted product through a related one (liquor brands advertising soda or music).</li><li><b>Influencer and creator marketing, content marketing, moment marketing</b> (topical posts, Amul style).</li></ul><p>Have one Indian example of each ready; panels love asking for one.</p>`, q: 'Give me one great example of moment marketing and why it worked.' },
  { k: 'research', t: 'Market research process and questionnaire design', h: `<ol><li>Define the problem and objectives.</li><li>Design: exploratory (qual), descriptive (surveys), causal (experiments).</li><li>Sampling: population, frame, method (random, stratified, convenience), size.</li><li>Collect data; check quality.</li><li>Analyse and interpret.</li><li>Present findings and recommendations.</li></ol><p><b>Questionnaire design:</b> one idea per question, neutral wording, logical flow (easy → sensitive), right scales (Likert, ranking), avoid double-barrelled and leading questions, pilot it.</p><p><b>Useful tools:</b> conjoint (trade-offs between features and price), NPS, brand trackers, A/B tests.</p>`, q: 'Design a 10-question survey to find why people stop using a fitness app.' },
  { k: 'laws', t: 'Brand archetypes, the 5Cs and the 22 laws', h: `<ul><li><b>Brand archetypes:</b> twelve personalities (hero, caregiver, explorer, rebel, sage, lover…) that shape tone: Nike as hero, Dove as caregiver.</li><li><b>5Cs:</b> company, customers, competitors, collaborators, context: a quick situation analysis.</li><li><b>Ries & Trout's laws, the ones to remember:</b> leadership (better to be first than better), category (if you can't be first, create a category to be first in), mind (first in the mind beats first in market), focus (own a word: Volvo = safety), perception (marketing is a battle of perceptions), line extension (extending too far weakens a brand).</li></ul>`, q: 'Which brand archetype is Titan? And Fastrack? Why does it matter?' }];

/* Company deep dives: one set per company, in the order you prepare (business → AI → value chain → leadership & campaigns → GTM) */
const D = (co, k, t, h, q, sub) => ({ k: co + '-' + k, co: [co], t, h, q, sub });
export const IND2 = [
  // Google
  D('google', 'ai', 'Google: AI at Google, and AI in advertising', `<ul><li><b>Google's AI:</b> Gemini models across products (Search with AI Overviews and AI Mode, Workspace, Android, Cloud); Google DeepMind as the research arm; TPUs (its own AI chips); Vertex AI on Google Cloud.</li><li><b>In ads:</b> Smart Bidding, Performance Max, AI-generated assets, conversational campaign setup, ads appearing inside AI search experiences, AI-powered measurement.</li><li><b>What it means for a strategist:</b> less manual tweaking, more work on inputs (conversion data, creative, product feeds, audiences) and on explaining results to advertisers.</li><li><b>In your role:</b> use AI to audit accounts, draft plans and reports faster; spend the saved time with clients.</li></ul><p><b>Check before the interview:</b> the latest Google Marketing Live and Search AI announcements.</p>`, 'How should a mid-market advertiser adapt to AI-driven campaigns?'),
  D('google', 'vc', 'The digital advertising value chain', `<p><b>Advertiser</b> (brand, budget, goals) → <b>agency</b> (strategy, media buying, creative) → <b>ad platforms</b> (Google, Meta, Amazon: auction, targeting, measurement) → <b>publishers and inventory</b> (Search, YouTube, partner sites and apps) → <b>users</b>. Around it: ad-tech (DSPs, SSPs, ad servers), measurement and analytics (GA4, attribution, brand lift), data and privacy rules.</p><p><b>Where money flows:</b> advertiser pays per click or impression; publisher gets a share on networks; agencies earn fees or commissions.</p><p><b>gTech's place:</b> helps advertisers (often without big agencies) get value from Google's products, so they spend more and stay.</p>`, 'Walk me through the value chain of a rupee spent on a YouTube ad.'),
  D('google', 'lead', 'Google: leadership, vision and campaigns to know', `<p><b>Look up (20 minutes):</b> one recent interview or keynote by Alphabet's CEO or Google's head of ads (search "Google Marketing Live keynote" and "Sundar Pichai interview" for the last few months); Google India's country head on Indian SMBs and AI.</p><p><b>Note three lines:</b> their stated goal, one quote, what it means for the role you're applying to.</p><p><b>Campaigns worth knowing:</b> "Reunion" (2013, Google Search: a cross-border friendship, a famous India–Pakistan emotional ad), the annual "Year in Search" films, Google Pixel launch campaigns, "Google for India" announcements. Pick one favourite and say why it worked.</p>`, 'What is your favourite Google campaign, and why did it work?'),
  D('google', 'gtm', 'Google: GTM and digital cases', `<p>Cases at gTech/GCS usually sit on the advertiser's side: grow sales or leads, fix a funnel, prove value, keep a client. Practise these out loud.</p>`, 'Plan how Google could bring 1 lakh first-time small advertisers from tier-2 cities onto Google Ads.', ['x47', 'x48', 'x49', 'x50', 'x51', 'x52', 'x42', 'x38']),
  // Accenture
  D('atci', 'ai', 'Accenture: AI at Accenture, and AI in IT services', `<ul><li><b>Accenture's AI push:</b> large investments in data and AI, GenAI and agentic AI offerings, partnerships with all major model and cloud companies, reskilling its workforce on AI, and AI to automate its own delivery.</li><li><b>In IT services:</b> AI shrinks routine work (testing, support, coding), shifts pricing from people-hours to outcomes, and creates new work in data platforms, AI integration, governance and change management.</li><li><b>In your role (analyst):</b> process mapping with AI, faster requirements and documentation, AI use-case discovery, adoption tracking.</li></ul><p><b>Check:</b> Accenture's latest quarterly comments on GenAI bookings and any recent AI acquisitions.</p>`, 'How is GenAI changing how IT services firms make money?'),
  D('atci', 'vc', 'The IT services and ERP implementation value chain', `<p><b>Software vendors</b> (SAP, Oracle, Workday, Salesforce, hyperscalers) → <b>system integrators and consultancies</b> (Accenture, Deloitte, IBM, Infosys: strategy, design, implementation, integration) → <b>client</b> (CIO, CFO, business teams) → <b>managed services</b> (run and support, often offshore) → <b>continuous improvement</b>.</p><p><b>Where money comes from:</b> consulting fees, implementation projects (time and materials or fixed price), multi-year managed services, partner incentives.</p><p><b>An analyst's place:</b> requirements, process mapping, configuration support, testing, training and adoption.</p>`, 'Who makes money at each stage of an SAP S/4HANA migration?'),
  D('atci', 'lead', 'Accenture: leadership, vision and positioning', `<p><b>Look up:</b> a recent interview or earnings-call comment from Accenture's CEO on "reinvention" and AI; Accenture India leadership on hiring and AI skills.</p><p><b>Positioning to know:</b> "reinvention" (strategy + technology + operations + AI as one offer), "360° value" for clients, Accenture Song (its marketing and creative arm), large AI investment and training commitments.</p><p><b>What it means for you:</b> analysts who can connect business process, data and AI adoption.</p>`, 'Accenture talks about "reinvention". What does it mean for a client?'),
  D('atci', 'gtm', 'Accenture: GTM and transformation cases', `<p>Tech Consulting cases: process, ERP, AI use cases, transformation roadmaps, and selling a new offering to clients.</p>`, 'Design how Accenture would sell an AI-led finance-close service to mid-sized Indian manufacturers.', ['x32', 'x33', 'x34', 'x35', 'x36', 'x37', 'x28', 'x31', 'x43']),
  // Titan
  D('titan', 'ai', 'Titan: AI and technology in jewellery and retail', `<ul><li><b>Uses in jewellery and lifestyle retail:</b> demand forecasting and inventory placement across stores, personalised recommendations, virtual try-on (jewellery, eyewear), design generation, customer-service assistants, gold-price-linked pricing, store analytics.</li><li><b>Omnichannel:</b> CaratLane is digital-first; Tanishq and eyewear blend online research with in-store purchase.</li><li><b>In an MT role:</b> AI-assisted market mapping, assortment decisions by store, campaign personalisation.</li></ul><p><b>Check:</b> recent Titan or CaratLane announcements on technology and omnichannel.</p>`, 'Where would AI create the most value for Tanishq?'),
  D('titan', 'vc', 'The jewellery and watch value chain', `<p><b>Jewellery:</b> gold and diamond sourcing (banks, bullion, mines) → refining → design → manufacturing (karigars, vendor units, own factories) → hallmarking (BIS) → distribution to stores (own and franchise) → sale (making charges, exchange of old gold) → after-sales (cleaning, buy-back).</p><p><b>Where margin sits:</b> making charges and studded jewellery earn more than plain gold; gold-exchange programmes win share from local jewellers.</p><p><b>Watches:</b> movements and components (in-house or imported) → assembly → brand → channels (brand stores, multi-brand outlets, large-format retail, online) → service.</p>`, 'Walk me through how Tanishq makes money on a ₹1 lakh necklace.'),
  D('titan', 'lead', 'Titan: leadership, vision and campaigns to know', `<p><b>Look up:</b> a recent interview of Titan's MD or the Tanishq CEO on growth, lightweight jewellery and international expansion; the latest investor-day vision.</p><p><b>Campaigns worth knowing:</b> Tanishq's remarriage ad (2013, a landmark in progressive advertising), Tanishq "Ekatvam" (2020, withdrawn after backlash: a lesson in brand risk), Fastrack "Move On" (youth attitude), Titan Raga (women's watches), Titan's "Be More" positioning, Mia by Tanishq for working women.</p><p><b>Pick one favourite:</b> what insight it used and what it did for the brand.</p>`, 'What is your favourite Tanishq campaign, and what did it do for the brand?'),
  D('titan', 'gtm', 'Titan: GTM and retail cases', `<p>MT panels test brand, retail and sales thinking: grow a business, launch a line, fix a store.</p>`, 'Launch a lightweight, daily-wear jewellery line for first-jobbers. Build the GTM.', ['c1', 'c3', 'c13', 'x5', 'x13', 'x44', 'x46', 'x48']),
  // Schneider
  D('schneider', 'ai', 'Schneider Electric: AI and energy technology', `<ul><li><b>Schneider's tech:</b> EcoStruxure platform (connected products, edge control, apps and analytics), digital twins, AI for energy optimisation, predictive maintenance and data-centre cooling and power.</li><li><b>AI as demand driver:</b> AI data centres need huge power and cooling, a major growth area for Schneider.</li><li><b>In B2B marketing:</b> AI for account selection and intent signals, personalised ABM content, lead scoring, sales-enablement assistants.</li></ul><p><b>Check:</b> Schneider's latest announcements on AI data centres and India.</p>`, 'How does the AI boom help Schneider Electric?'),
  D('schneider', 'vc', 'The energy management value chain (B2B)', `<p><b>Components and products</b> (breakers, switchgear, UPS, drives, sensors) → <b>systems and software</b> (EcoStruxure, building and energy management) → <b>channel</b>: distributors, panel builders, system integrators, electrical contractors → <b>specifiers</b> (consultants, architects, EPC firms) who write products into project designs → <b>end users</b> (buildings, data centres, factories, utilities, homes) → <b>services</b> (maintenance, energy audits).</p><p><b>For marketing:</b> you must win the specifier and the channel, not just the end buyer. Long cycles, many influencers.</p>`, 'Who decides which switchgear brand goes into a new hospital building?'),
  D('schneider', 'lead', 'Schneider: leadership, vision and campaigns to know', `<p><b>Look up:</b> a recent interview of Schneider's global CEO or India MD on sustainability, electrification and data centres; Schneider's sustainability goals.</p><p><b>Positioning:</b> "Life Is On", "impact company", energy technology partner; regular rankings as one of the world's most sustainable companies.</p><p><b>For a marketing role:</b> know one Schneider India campaign or event, and one thought-leadership report it published.</p>`, 'What does "Life Is On" mean for how Schneider markets itself?'),
  D('schneider', 'gtm', 'Schneider: GTM and B2B cases', `<p>B2B marketing cases: create pipeline, enter a segment, work through channel partners and specifiers.</p>`, 'Build a GTM for a smart home-energy management system for premium Indian homes.', ['c17', 'x19', 'x26', 'c5', 'x9']),
  // Versuni
  D('versuni', 'ai', 'Versuni: AI and digital in small appliances', `<ul><li><b>Product:</b> connected appliances (app-controlled air fryers, coffee machines), recipe apps and content.</li><li><b>Commerce:</b> e-commerce and quick commerce analytics, review management, AI-assisted search and product discovery.</li><li><b>Sales:</b> AI for demand forecasting, dealer ordering apps, retail execution tracking.</li><li><b>Marketing:</b> AI-generated recipe and product content, regional-language creative at scale.</li></ul>`, 'How could AI help Philips sell more air fryers in India?'),
  D('versuni', 'vc', 'The kitchen-appliance value chain', `<p><b>Component suppliers</b> (motors, jars, plastics, electronics; many from China) → <b>manufacturing</b> (own plants or contract manufacturers) → <b>C&F / warehouses</b> → <b>distributors</b> → <b>retail</b>: multi-brand dealers, large-format retail (Croma, Reliance Digital), modern trade, e-commerce and quick commerce, brand stores → <b>consumer</b> → <b>service network</b> (installation, repairs, warranty).</p><p><b>Where it's won:</b> dealer push (margins, schemes, demos, in-store promoters) and online reviews and ratings.</p>`, 'How does a Philips mixer-grinder reach a home in Madurai?'),
  D('versuni', 'lead', 'Versuni: leadership, vision and campaigns to know', `<p><b>Look up:</b> Versuni's story since leaving Philips (ownership, strategy), Versuni India leadership interviews, Preethi's South-India heritage.</p><p><b>Campaigns:</b> recent Philips air fryer campaigns ("healthy frying"), Preethi's mixer-grinder durability messaging. Note one you like and why.</p>`, 'How should Versuni use the Philips and Preethi brands differently?'),
  D('versuni', 'gtm', 'Versuni: GTM and sales cases', `<p>MT cases: launch a product, grow a channel, fix margins, win the dealer.</p>`, 'Launch an air fryer for tier-2 households. Build the GTM.', ['c2', 'c4', 'c5', 'c12', 'x2', 'x3', 'x15', 'x44']),
  // CleverTap
  D('clevertap', 'ai', 'CleverTap: AI in customer engagement', `<ul><li><b>In engagement platforms:</b> predictive segments (likely to churn or buy), best time and channel to send, AI-written message variants, recommendations, AI assistants that build campaigns from a brief.</li><li><b>Value to clients:</b> higher retention and conversion with less manual work.</li><li><b>For a CSM:</b> use AI insights in QBRs, spot at-risk accounts early, show ROI.</li></ul><p><b>Check:</b> CleverTap's current AI features on its website and any recent launches.</p>`, 'How would you show a client the ROI of AI-powered personalisation?'),
  D('clevertap', 'vc', 'The martech and customer-engagement value chain', `<p><b>Data</b> (app and web events, CRM, purchases) → <b>engagement platform</b> (analytics, segments, journeys, messaging) → <b>channels</b> (push, in-app, email, SMS, WhatsApp, often via channel partners) → <b>client's marketing and growth team</b> → <b>end users</b>. Around it: integrations (CDPs, ad platforms, data warehouses), agencies and partners.</p><p><b>CleverTap earns</b> subscriptions priced on users or events, plus messaging fees; growth comes from expansion within accounts (NRR).</p>`, 'Where does CleverTap sit in a fintech app\'s marketing stack?'),
  D('clevertap', 'lead', 'CleverTap: leadership, vision and customers', `<p><b>Look up:</b> recent interviews of CleverTap's founders or CEO on AI and retention; two customer case studies with metrics.</p><p><b>Positioning:</b> an all-in-one engagement and retention platform for consumer brands, strong in India, Southeast Asia and the Middle East.</p>`, 'Why would a client choose CleverTap over a competitor?'),
  D('clevertap', 'gtm', 'CleverTap: GTM and retention cases', `<p>CSM cases: adoption, churn, expansion, ROI stories.</p>`, 'Build a GTM for a WhatsApp-commerce add-on sold to Indian D2C brands.', ['x7', 'x11', 'x39', 'x41', 'x50', 'x19', 'x26', 'x27']),
  // Pine Labs
  D('pinelabs', 'ai', 'Pine Labs: AI in payments and merchant commerce', `<ul><li><b>Uses:</b> fraud detection and risk scoring, smart routing of transactions, merchant insights and analytics, personalised EMI and offers at checkout, customer-service automation, credit underwriting for merchants.</li><li><b>For marketing:</b> AI-personalised merchant campaigns, sales-enablement content at scale, community content.</li></ul><p><b>Check:</b> Pine Labs' latest product announcements and news (listing, results).</p>`, 'How can AI make EMI-at-checkout more useful for shoppers?'),
  D('pinelabs', 'vc', 'The payments value chain', `<p><b>Card or UPI payment:</b> consumer → <b>issuer</b> (consumer's bank) → <b>card network / NPCI</b> → <b>acquirer</b> (merchant's bank) and <b>payment aggregator / POS provider</b> (Pine Labs) → <b>merchant</b>.</p><p><b>Money:</b> the merchant discount rate (MDR) is shared between issuer, network and acquirer; UPI has near-zero MDR, so players earn from terminals, software, EMI and offers, lending and value-added services.</p><p><b>EMI at checkout:</b> brands and banks fund "no-cost EMI" (subvention) to drive sales; Pine Labs connects brand, bank and merchant.</p>`, 'Who earns what when you pay ₹10,000 by card at a store using a Pine Labs terminal?'),
  D('pinelabs', 'lead', 'Pine Labs: leadership, vision and positioning', `<p><b>Look up:</b> a recent interview of Pine Labs' CEO on merchant commerce, affordability and international growth; its listing and latest results.</p><p><b>Positioning:</b> merchant commerce platform: payments, affordability (EMI), gift cards and prepaid, software for merchants and brands.</p>`, 'Where should Pine Labs grow next, and why?'),
  D('pinelabs', 'gtm', 'Pine Labs: GTM and fintech cases', `<p>Marketing MT cases: merchant acquisition, community, sales enablement, new markets.</p>`, 'Build a GTM to get electronics stores in tier-2 cities to offer EMI at checkout.', ['x10', 'x36', 'x41', 'x42', 'c6']),
  // IBM
  D('ibm', 'ai', 'IBM: watsonx, AI governance and hybrid cloud', `<ul><li><b>IBM's AI:</b> watsonx (build and run AI models, data platform, governance), its own Granite models (open, enterprise-focused), AI assistants and agents for business (HR, customer service, IT), automation software.</li><li><b>Positioning:</b> trusted, governed AI for regulated enterprises, deployable on any cloud or on-premises (hybrid via Red Hat OpenShift).</li><li><b>For a product marketer:</b> translate this into buyer outcomes (cost, risk, speed) by persona.</li></ul><p><b>Check:</b> IBM's latest Think conference announcements.</p>`, 'Why would a bank pick IBM for AI over a hyperscaler?'),
  D('ibm', 'vc', 'The enterprise software value chain', `<p><b>R&D and product</b> → <b>product marketing</b> (positioning, messaging, launches) → <b>routes to market</b>: direct sales, partners and resellers, global system integrators, cloud marketplaces → <b>enterprise buyers</b> (CIO, CDO, business owners, procurement) → <b>implementation and support</b> → <b>renewal and expansion</b>.</p><p><b>Revenue models:</b> subscriptions and licences, consumption, support contracts, consulting.</p>`, 'How does IBM software reach a large Indian bank, and who influences the decision?'),
  D('ibm', 'lead', 'IBM: leadership, vision and campaigns to know', `<p><b>Look up:</b> a recent interview or Think keynote from IBM's CEO on hybrid cloud and AI; IBM India leadership on enterprise AI adoption.</p><p><b>Campaigns:</b> "Let's create" (brand platform), "Smarter Planet" (2008, a classic B2B positioning campaign), Watson on Jeopardy (2011, a famous AI moment). Pick one and say what it did.</p>`, 'Which IBM campaign do you admire, and what made it work for a B2B brand?'),
  D('ibm', 'gtm', 'IBM: GTM and product-marketing cases', `<p>PMM cases: position a product, plan a launch, enable sales, beat a competitor.</p>`, 'Build a 90-day GTM for an AI-governance product aimed at Indian banks.', ['x28', 'x31', 'x32', 'c16', 'c21', 'x19', 'x26'])];

